    out = [[0] * w for _ in range(h)]
    for obj in objects:
        top = min(y for y, _, _ in obj)
        shift = target_top - top
        for y, x, color in obj:
            ny = y + shift
            if 0 <= ny < h:
                out[ny][x] = color
    return out
